function validate(input) {
  const [{ Seat = [] }] = input;
  const ids = new Set();
  for (const [id] of Seat) {
    if (id === null) return 'Every seat needs an id.';
    if (ids.has(id)) return `Seat id ${id} appears twice.`;
    ids.add(id);
  }
  for (let id = 1; id <= Seat.length; id++) if (!ids.has(id)) return `Seat ids must be 1 to ${Seat.length}; ${id} is missing.`;
  return null;
}

