function generate(rand, size) {
  const names = ['Abbot', 'Doris', 'Emerson', 'Green', 'Jeames', 'Ana', 'Lee', 'Kim'];
  const count = size === 'small' ? Math.floor(rand() * 9) : 1999 + Math.floor(rand() * 2);
  const Seat = [];
  for (let id = 1; id <= count; id++) Seat.push([id, size === 'small' ? names[Math.floor(rand() * names.length)] : `Student${id}`]);
  // Store the rows in a shuffled order so the query cannot rely on the table's physical order.
  for (let i = Seat.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Seat[i], Seat[j]] = [Seat[j], Seat[i]];
  }
  return [{ Seat }];
}
